    pub const VT_WHEEL_MOMENTUM_CAPACITY_NMS: ::flatbuffers::VOffsetT = 30;
    pub const VT_FINE_POINTING_THRESHOLD_DEG: ::flatbuffers::VOffsetT = 32;
    pub const VT_SOLAR_ARRAY: ::flatbuffers::VOffsetT = 34;
    pub const VT_BATTERY: ::flatbuffers::VOffsetT = 36;
    pub const VT_BUS_LOAD_W: ::flatbuffers::VOffsetT = 38;
    pub const VT_SENSOR_NOISE_ARCSEC: ::flatbuffers::VOffsetT = 40;
    pub const VT_RELATIVE_TARGET_ID: ::flatbuffers::VOffsetT = 42;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        ppsScenario { _tab: table }
    }

