        builder.add_SENSOR_NOISE_ARCSEC(args.SENSOR_NOISE_ARCSEC);
        builder.add_BUS_LOAD_W(args.BUS_LOAD_W);
        builder.add_FINE_POINTING_THRESHOLD_DEG(args.FINE_POINTING_THRESHOLD_DEG);
        builder.add_WHEEL_MOMENTUM_CAPACITY_NMS(args.WHEEL_MOMENTUM_CAPACITY_NMS);
        builder.add_INITIAL_WHEEL_MOMENTUM_NMS(args.INITIAL_WHEEL_MOMENTUM_NMS);
