        builder.add_DURATION_S(args.DURATION_S);
        builder.add_START_EPOCH_MS(args.START_EPOCH_MS);
        if let Some(x) = args.RELATIVE_TARGET_ID { builder.add_RELATIVE_TARGET_ID(x); }
        if let Some(x) = args.BATTERY { builder.add_BATTERY(x); }
