impl ppsScenarioT {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<ppsScenario<'b>> {
        let SCENARIO_ID = self.SCENARIO_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let NAME = self.NAME.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let START_EPOCH_MS = self.START_EPOCH_MS;
        let DURATION_S = self.DURATION_S;
        let STEP_S = self.STEP_S;
        let OBJECT_ID = self.OBJECT_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let BUS_SPECIFICATION = self.BUS_SPECIFICATION.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let TRAJECTORY = self.TRAJECTORY.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let POINTING = self.POINTING.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|t| t.pack(_fbb)).collect();_fbb.create_vector(&w)
        });
        let INITIAL_ATTITUDE = self.INITIAL_ATTITUDE.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let INITIAL_POINTING_ERROR_DEG = self.INITIAL_POINTING_ERROR_DEG;
        let INITIAL_BODY_RATE_DEG_S = self.INITIAL_BODY_RATE_DEG_S;
        let INITIAL_WHEEL_MOMENTUM_NMS = self.INITIAL_WHEEL_MOMENTUM_NMS;
        let WHEEL_MOMENTUM_CAPACITY_NMS = self.WHEEL_MOMENTUM_CAPACITY_NMS;
        let FINE_POINTING_THRESHOLD_DEG = self.FINE_POINTING_THRESHOLD_DEG;
        let SOLAR_ARRAY = self.SOLAR_ARRAY.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let BATTERY = self.BATTERY.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let BUS_LOAD_W = self.BUS_LOAD_W;
        let SENSOR_NOISE_ARCSEC = self.SENSOR_NOISE_ARCSEC;
        let RELATIVE_TARGET_ID = self.RELATIVE_TARGET_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        ppsScenario::create(_fbb, &ppsScenarioArgs{
            SCENARIO_ID,
            NAME,
            START_EPOCH_MS,
            DURATION_S,
            STEP_S,
            OBJECT_ID,
            BUS_SPECIFICATION,
            TRAJECTORY,
            POINTING,
            INITIAL_ATTITUDE,
            INITIAL_POINTING_ERROR_DEG,
            INITIAL_BODY_RATE_DEG_S,
            INITIAL_WHEEL_MOMENTUM_NMS,
            WHEEL_MOMENTUM_CAPACITY_NMS,
            FINE_POINTING_THRESHOLD_DEG,
            SOLAR_ARRAY,
            BATTERY,
            BUS_LOAD_W,
            SENSOR_NOISE_ARCSEC,
            RELATIVE_TARGET_ID,
        })
    }
}

pub enum ppsTelemetryOffset {}

/// The telemetry: simulated time series, column-major and parallel. An empty
/// series was not produced.
#[derive(Copy, Clone, PartialEq)]
pub struct ppsTelemetry<'a> {
    pub _tab: ::flatbuffers::Table<'a>,
}

impl<'a> ::flatbuffers::Follow<'a> for ppsTelemetry<'a> {
    type Inner = ppsTelemetry<'a>;

    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self { _tab: unsafe { ::flatbuffers::Table::new(buf, loc) } }
    }
}

