pub enum PPSOffset {}

/// Pointing and Power Scenario - a scenario, and the telemetry a run of it
/// produced.
#[derive(Copy, Clone, PartialEq)]
pub struct PPS<'a> {
    pub _tab: ::flatbuffers::Table<'a>,
}

impl<'a> ::flatbuffers::Follow<'a> for PPS<'a> {
    type Inner = PPS<'a>;

    #[inline]
    unsafe fn follow(buf: &'a [u8], loc: usize) -> Self::Inner {
        Self { _tab: unsafe { ::flatbuffers::Table::new(buf, loc) } }
    }
}

impl<'a> PPS<'a> {
    pub const VT_RUN_ID: ::flatbuffers::VOffsetT = 4;
    pub const VT_CREATED_AT_MS: ::flatbuffers::VOffsetT = 6;
    pub const VT_PROVIDER: ::flatbuffers::VOffsetT = 8;
    pub const VT_SCENARIO: ::flatbuffers::VOffsetT = 10;
    pub const VT_STATUS: ::flatbuffers::VOffsetT = 12;
    pub const VT_ERROR_CODE: ::flatbuffers::VOffsetT = 14;
    pub const VT_ERROR_MESSAGE: ::flatbuffers::VOffsetT = 16;
    pub const VT_PRODUCTS: ::flatbuffers::VOffsetT = 18;
    pub const VT_ASSUMPTIONS: ::flatbuffers::VOffsetT = 20;
    pub const VT_TELEMETRY: ::flatbuffers::VOffsetT = 22;

    #[inline]
    pub unsafe fn init_from_table(table: ::flatbuffers::Table<'a>) -> Self {
        PPS { _tab: table }
    }

    #[allow(unused_mut)]
    pub fn create<'bldr: 'args, 'args: 'mut_bldr, 'mut_bldr, A: ::flatbuffers::Allocator + 'bldr>(
        _fbb: &'mut_bldr mut ::flatbuffers::FlatBufferBuilder<'bldr, A>,
        args: &'args PPSArgs<'args>
    ) -> ::flatbuffers::WIPOffset<PPS<'bldr>> {
        let mut builder = PPSBuilder::new(_fbb);
        builder.add_CREATED_AT_MS(args.CREATED_AT_MS);
        if let Some(x) = args.TELEMETRY { builder.add_TELEMETRY(x); }
        if let Some(x) = args.ASSUMPTIONS { builder.add_ASSUMPTIONS(x); }
        if let Some(x) = args.PRODUCTS { builder.add_PRODUCTS(x); }
        if let Some(x) = args.ERROR_MESSAGE { builder.add_ERROR_MESSAGE(x); }
        if let Some(x) = args.ERROR_CODE { builder.add_ERROR_CODE(x); }
        if let Some(x) = args.SCENARIO { builder.add_SCENARIO(x); }
        if let Some(x) = args.PROVIDER { builder.add_PROVIDER(x); }
        if let Some(x) = args.RUN_ID { builder.add_RUN_ID(x); }
        builder.add_STATUS(args.STATUS);
        builder.finish()
    }

    pub fn unpack(&self) -> PPST {
        let RUN_ID = self.RUN_ID().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let CREATED_AT_MS = self.CREATED_AT_MS();
        let PROVIDER = self.PROVIDER().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let SCENARIO = self.SCENARIO().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        let STATUS = self.STATUS();
        let ERROR_CODE = self.ERROR_CODE().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let ERROR_MESSAGE = self.ERROR_MESSAGE().map(|x| {
            alloc::string::ToString::to_string(x)
        });
        let PRODUCTS = self.PRODUCTS().map(|x| {
            x.into_iter().collect()
        });
        let ASSUMPTIONS = self.ASSUMPTIONS().map(|x| {
            x.iter().map(|s| alloc::string::ToString::to_string(s)).collect()
        });
        let TELEMETRY = self.TELEMETRY().map(|x| {
            alloc::boxed::Box::new(x.unpack())
        });
        PPST {
            RUN_ID,
            CREATED_AT_MS,
            PROVIDER,
            SCENARIO,
            STATUS,
            ERROR_CODE,
            ERROR_MESSAGE,
            PRODUCTS,
            ASSUMPTIONS,
            TELEMETRY,
        }
    }

    /// Identifier of the run; empty = not assigned.
    #[inline]
    pub fn RUN_ID(&self) -> Option<&'a str> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<&str>>(PPS::VT_RUN_ID, None)}
    }

    /// Unix milliseconds the run was made.
    #[inline]
    pub fn CREATED_AT_MS(&self) -> i64 {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<i64>(PPS::VT_CREATED_AT_MS, Some(0)).unwrap()}
    }

    /// Identifier of the simulator that ran it.
    #[inline]
    pub fn PROVIDER(&self) -> Option<&'a str> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<&str>>(PPS::VT_PROVIDER, None)}
    }

    #[inline]
    pub fn SCENARIO(&self) -> Option<ppsScenario<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<ppsScenario>>(PPS::VT_SCENARIO, None)}
    }

    #[inline]
    pub fn STATUS(&self) -> ppsStatus {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<ppsStatus>(PPS::VT_STATUS, Some(ppsStatus::Pending)).unwrap()}
    }

    /// Stable machine-readable reason for InvalidRequest or Failed.
    #[inline]
    pub fn ERROR_CODE(&self) -> Option<&'a str> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<&str>>(PPS::VT_ERROR_CODE, None)}
    }

    #[inline]
    pub fn ERROR_MESSAGE(&self) -> Option<&'a str> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<&str>>(PPS::VT_ERROR_MESSAGE, None)}
    }

    /// Products the telemetry carries.
    #[inline]
    pub fn PRODUCTS(&self) -> Option<::flatbuffers::Vector<'a, ppsProduct>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, ppsProduct>>>(PPS::VT_PRODUCTS, None)}
    }

    /// Modelling assumptions and simplifications of the run, as text.
    #[inline]
    pub fn ASSUMPTIONS(&self) -> Option<::flatbuffers::Vector<'a, ::flatbuffers::ForwardsUOffset<&'a str>>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'a, ::flatbuffers::ForwardsUOffset<&'a str>>>>(PPS::VT_ASSUMPTIONS, None)}
    }

    #[inline]
    pub fn TELEMETRY(&self) -> Option<ppsTelemetry<'a>> {
        // Safety:
        // Created from valid Table for this object
        // which contains a valid value in this slot
        unsafe { self._tab.get::<::flatbuffers::ForwardsUOffset<ppsTelemetry>>(PPS::VT_TELEMETRY, None)}
    }
}

impl ::flatbuffers::Verifiable for PPS<'_> {
    #[inline]
    fn run_verifier(
        v: &mut ::flatbuffers::Verifier, pos: usize
    ) -> Result<(), ::flatbuffers::InvalidFlatbuffer> {
        v.visit_table(pos)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("RUN_ID", Self::VT_RUN_ID, false)?
            .visit_field::<i64>("CREATED_AT_MS", Self::VT_CREATED_AT_MS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("PROVIDER", Self::VT_PROVIDER, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<ppsScenario>>("SCENARIO", Self::VT_SCENARIO, false)?
            .visit_field::<ppsStatus>("STATUS", Self::VT_STATUS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("ERROR_CODE", Self::VT_ERROR_CODE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<&str>>("ERROR_MESSAGE", Self::VT_ERROR_MESSAGE, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ppsProduct>>>("PRODUCTS", Self::VT_PRODUCTS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<::flatbuffers::Vector<'_, ::flatbuffers::ForwardsUOffset<&'_ str>>>>("ASSUMPTIONS", Self::VT_ASSUMPTIONS, false)?
            .visit_field::<::flatbuffers::ForwardsUOffset<ppsTelemetry>>("TELEMETRY", Self::VT_TELEMETRY, false)?
            .finish();
        Ok(())
    }
}

