pub struct PPSBuilder<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> {
    fbb_: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    start_: ::flatbuffers::WIPOffset<::flatbuffers::TableUnfinishedWIPOffset>,
}

impl<'a: 'b, 'b, A: ::flatbuffers::Allocator + 'a> PPSBuilder<'a, 'b, A> {
    #[inline]
    pub fn add_RUN_ID(&mut self, RUN_ID: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(PPS::VT_RUN_ID, RUN_ID);
    }

    #[inline]
    pub fn add_CREATED_AT_MS(&mut self, CREATED_AT_MS: i64) {
        self.fbb_.push_slot::<i64>(PPS::VT_CREATED_AT_MS, CREATED_AT_MS, 0);
    }

    #[inline]
    pub fn add_PROVIDER(&mut self, PROVIDER: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(PPS::VT_PROVIDER, PROVIDER);
    }

    #[inline]
    pub fn add_SCENARIO(&mut self, SCENARIO: ::flatbuffers::WIPOffset<ppsScenario<'b >>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<ppsScenario>>(PPS::VT_SCENARIO, SCENARIO);
    }

    #[inline]
    pub fn add_STATUS(&mut self, STATUS: ppsStatus) {
        self.fbb_.push_slot::<ppsStatus>(PPS::VT_STATUS, STATUS, ppsStatus::Pending);
    }

    #[inline]
    pub fn add_ERROR_CODE(&mut self, ERROR_CODE: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(PPS::VT_ERROR_CODE, ERROR_CODE);
    }

    #[inline]
    pub fn add_ERROR_MESSAGE(&mut self, ERROR_MESSAGE: ::flatbuffers::WIPOffset<&'b  str>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(PPS::VT_ERROR_MESSAGE, ERROR_MESSAGE);
    }

    #[inline]
    pub fn add_PRODUCTS(&mut self, PRODUCTS: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , ppsProduct>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(PPS::VT_PRODUCTS, PRODUCTS);
    }

    #[inline]
    pub fn add_ASSUMPTIONS(&mut self, ASSUMPTIONS: ::flatbuffers::WIPOffset<::flatbuffers::Vector<'b , ::flatbuffers::ForwardsUOffset<&'b  str>>>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<_>>(PPS::VT_ASSUMPTIONS, ASSUMPTIONS);
    }

    #[inline]
    pub fn add_TELEMETRY(&mut self, TELEMETRY: ::flatbuffers::WIPOffset<ppsTelemetry<'b >>) {
        self.fbb_.push_slot_always::<::flatbuffers::WIPOffset<ppsTelemetry>>(PPS::VT_TELEMETRY, TELEMETRY);
    }

    #[inline]
    pub fn new(_fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>) -> PPSBuilder<'a, 'b, A> {
        let start = _fbb.start_table();
        PPSBuilder {
            fbb_: _fbb,
            start_: start,
        }
    }

    #[inline]
    pub fn finish(self) -> ::flatbuffers::WIPOffset<PPS<'a>> {
        let o = self.fbb_.end_table(self.start_);
        ::flatbuffers::WIPOffset::new(o.value())
    }
}

impl ::core::fmt::Debug for PPS<'_> {
    fn fmt(&self, f: &mut ::core::fmt::Formatter<'_>) -> ::core::fmt::Result {
        let mut ds = f.debug_struct("PPS");
        ds.field("RUN_ID", &self.RUN_ID());
        ds.field("CREATED_AT_MS", &self.CREATED_AT_MS());
        ds.field("PROVIDER", &self.PROVIDER());
        ds.field("SCENARIO", &self.SCENARIO());
        ds.field("STATUS", &self.STATUS());
        ds.field("ERROR_CODE", &self.ERROR_CODE());
        ds.field("ERROR_MESSAGE", &self.ERROR_MESSAGE());
        ds.field("PRODUCTS", &self.PRODUCTS());
        ds.field("ASSUMPTIONS", &self.ASSUMPTIONS());
        ds.field("TELEMETRY", &self.TELEMETRY());
        ds.finish()
    }
}

#[non_exhaustive]
#[derive(Debug, Clone, PartialEq)]
pub struct PPST {
    pub RUN_ID: Option<alloc::string::String>,
    pub CREATED_AT_MS: i64,
    pub PROVIDER: Option<alloc::string::String>,
    pub SCENARIO: Option<alloc::boxed::Box<ppsScenarioT>>,
    pub STATUS: ppsStatus,
    pub ERROR_CODE: Option<alloc::string::String>,
    pub ERROR_MESSAGE: Option<alloc::string::String>,
    pub PRODUCTS: Option<alloc::vec::Vec<ppsProduct>>,
    pub ASSUMPTIONS: Option<alloc::vec::Vec<alloc::string::String>>,
    pub TELEMETRY: Option<alloc::boxed::Box<ppsTelemetryT>>,
}

impl Default for PPST {
    fn default() -> Self {
        Self {
            RUN_ID: None,
            CREATED_AT_MS: 0,
            PROVIDER: None,
            SCENARIO: None,
            STATUS: ppsStatus::Pending,
            ERROR_CODE: None,
            ERROR_MESSAGE: None,
            PRODUCTS: None,
            ASSUMPTIONS: None,
            TELEMETRY: None,
        }
    }
}

impl PPST {
    pub fn pack<'b, A: ::flatbuffers::Allocator + 'b>(
        &self,
        _fbb: &mut ::flatbuffers::FlatBufferBuilder<'b, A>
    ) -> ::flatbuffers::WIPOffset<PPS<'b>> {
        let RUN_ID = self.RUN_ID.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let CREATED_AT_MS = self.CREATED_AT_MS;
        let PROVIDER = self.PROVIDER.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let SCENARIO = self.SCENARIO.as_ref().map(|x|{
            x.pack(_fbb)
        });
        let STATUS = self.STATUS;
        let ERROR_CODE = self.ERROR_CODE.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let ERROR_MESSAGE = self.ERROR_MESSAGE.as_ref().map(|x|{
            _fbb.create_string(x)
        });
        let PRODUCTS = self.PRODUCTS.as_ref().map(|x|{
            _fbb.create_vector(x)
        });
        let ASSUMPTIONS = self.ASSUMPTIONS.as_ref().map(|x|{
            let w: alloc::vec::Vec<_> = x.iter().map(|s| _fbb.create_string(s)).collect();_fbb.create_vector(&w)
        });
        let TELEMETRY = self.TELEMETRY.as_ref().map(|x|{
            x.pack(_fbb)
        });
        PPS::create(_fbb, &PPSArgs{
            RUN_ID,
            CREATED_AT_MS,
            PROVIDER,
            SCENARIO,
            STATUS,
            ERROR_CODE,
            ERROR_MESSAGE,
            PRODUCTS,
            ASSUMPTIONS,
            TELEMETRY,
        })
    }
}

/// Verifies that a buffer of bytes contains a `PPS`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_pps_unchecked`.
#[inline]
pub fn root_as_pps(buf: &[u8]) -> Result<PPS<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<PPS>(buf)
}

/// Verifies that a buffer of bytes contains a size prefixed
/// `PPS` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `size_prefixed_root_as_pps_unchecked`.
#[inline]
pub fn size_prefixed_root_as_pps(buf: &[u8]) -> Result<PPS<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root::<PPS>(buf)
}

/// Verifies, with the given options, that a buffer of bytes
/// contains a `PPS` and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_pps_unchecked`.
#[inline]
pub fn root_as_pps_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<PPS<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root_with_opts::<PPS<'b>>(opts, buf)
}

/// Verifies, with the given verifier options, that a buffer of
/// bytes contains a size prefixed `PPS` and returns
/// it. Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_pps_unchecked`.
#[inline]
pub fn size_prefixed_root_as_pps_with_opts<'b, 'o>(
    opts: &'o ::flatbuffers::VerifierOptions,
    buf: &'b [u8],
) -> Result<PPS<'b>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::size_prefixed_root_with_opts::<PPS<'b>>(opts, buf)
}

/// Assumes, without verification, that a buffer of bytes contains a PPS and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid `PPS`.
#[inline]
pub unsafe fn root_as_pps_unchecked(buf: &[u8]) -> PPS<'_> {
    unsafe { ::flatbuffers::root_unchecked::<PPS>(buf) }
}

/// Assumes, without verification, that a buffer of bytes contains a size prefixed PPS and returns it.
/// # Safety
/// Callers must trust the given bytes do indeed contain a valid size prefixed `PPS`.
#[inline]
pub unsafe fn size_prefixed_root_as_pps_unchecked(buf: &[u8]) -> PPS<'_> {
    unsafe { ::flatbuffers::size_prefixed_root_unchecked::<PPS>(buf) }
}

pub const PPS_IDENTIFIER: &str = "$PPS";

#[inline]
pub fn pps_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, PPS_IDENTIFIER, false)
}

#[inline]
pub fn pps_size_prefixed_buffer_has_identifier(buf: &[u8]) -> bool {
    ::flatbuffers::buffer_has_identifier(buf, PPS_IDENTIFIER, true)
}

#[inline]
pub fn finish_pps_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<PPS<'a>>
) {
    fbb.finish(root, Some(PPS_IDENTIFIER));
}

#[inline]
pub fn finish_size_prefixed_pps_buffer<'a, 'b, A: ::flatbuffers::Allocator + 'a>(
    fbb: &'b mut ::flatbuffers::FlatBufferBuilder<'a, A>,
    root: ::flatbuffers::WIPOffset<PPS<'a>>
) {
    fbb.finish_size_prefixed(root, Some(PPS_IDENTIFIER));
}
